<?php
declare(strict_types=1);
namespace App\Booking\Public\Redemption;
final class RedeemLedger { public function __construct(private \PDO $db){} public function claim(string $key,int $owner,string $fingerprint):bool {if($owner<1||!preg_match('/^[0-9a-f]{64}$/D',$key)||!preg_match('/^[0-9a-f]{64}$/D',$fingerprint))throw new \InvalidArgumentException('Invalid claim');$s=$this->db->prepare('INSERT INTO titan_booking_intent_claims (claim_key, owner_id, fingerprint, state) VALUES (?, ?, ?, ?) ON CONFLICT (claim_key) DO NOTHING');if($s===false||$s->execute([$key,$owner,$fingerprint,'claimed'])!==true)throw new \RuntimeException('Booking claim insert failed');return $s->rowCount()===1;} public function read(string $key):?array {$s=$this->db->prepare('SELECT claim_key,owner_id,fingerprint,state,booking_id FROM titan_booking_intent_claims WHERE claim_key = ? FOR UPDATE');if($s===false||$s->execute([$key])!==true)throw new \RuntimeException('Booking claim read failed');$row=$s->fetch(\PDO::FETCH_ASSOC);return $row?:null;} public function commit(string $key,int $owner,string $fingerprint,int $bookingId):bool{if($bookingId<1)throw new \InvalidArgumentException('Invalid booking');$s=$this->db->prepare("UPDATE titan_booking_intent_claims SET state='committed', booking_id=?, updated_at=now() WHERE claim_key=? AND owner_id=? AND fingerprint=? AND state='claimed'");if($s===false||$s->execute([$bookingId,$key,$owner,$fingerprint])!==true)throw new \RuntimeException('Booking claim update failed');return $s->rowCount()===1;} }
